mapper.delete:
delete from kb_async_tasks
where status not in 
  and delivery_status not in 
  and completed_at < #{before}
limit #{limit}

mapper.select:
select 
from kb_async_tasks


        and (task_code like concat('%', #{keyword}, '%')
             or upstream_task_id like concat('%', #{keyword}, '%'))


        and profile_code = #{profileCode}


        and protocol = #{protocol}



        and status = #{status}


        and submitted_at >= #{submittedFrom}


        and submitted_at <= #{submittedTo}


order by submitted_at desc, id desc

mapper.update:
update kb_async_tasks
set claim_id = #{claimId},
    claim_expires_at = #{claimExpires}
where id = #{id}
  and status in 
  and (claim_id is null or claim_expires_at < now(3))
